<?= $this->extend('layouts/tenant_admin') ?><?= $this->section('content') ?><?php $tenantContext=service('tenantContextManager')->current();$can=static fn(string $authority):bool=>service('tenantAccess')->hasAuthority($tenantContext,$authority);?>
<header class="page-head"><p class="eyebrow">Admissions operations</p><h1>Admissions dashboard</h1><p>Setup, review, publication, acceptance, and delivery health for this school.</p></header>
<section class="metric-grid" aria-label="Admissions metrics"><?php foreach(['Admission cycles'=>$cycleCount,'Open programmes'=>$openProgrammeCount,'Configured requirements'=>$requirementCount+$subjectRequirementCount+$documentRequirementCount,'Submitted applications'=>$submittedApplicationCount,'Review queue'=>$reviewQueueCount,'Screened applications'=>$screenedApplicationCount,'Offered applicants'=>$offeredApplicationCount,'Published lists'=>$publishedListCount,'Accepted offers'=>$acceptedOfferCount,'Cleared applicants'=>$clearedApplicantCount,'Conversion eligible'=>$conversionEligibleCount,'Pending notifications'=>$pendingOutboxCount,'Failed notifications'=>$failedOutboxCount] as $label=>$value):?><article class="metric"><strong><?= esc($value) ?></strong><span><?= esc($label) ?></span></article><?php endforeach?></section>
<section class="action-grid" aria-label="Admissions workspaces"><?php foreach([['admissions.cycles.manage','tenant/admissions/cycles','Admission cycles','Configure application windows and lifecycle.'],['admissions.programmes.manage','tenant/admissions/programmes','Programme openings','Open configured programmes for applications.'],['admissions.requirements.manage','tenant/admissions/requirements','Requirements','Configure subject and document requirements.'],['admissions.applications.view','tenant/admissions/applications','Application review','Review submissions and request corrections.'],['admissions.decisions.manage','tenant/admissions/decisions','Decisions','Screen, shortlist, decide, and approve.'],['admissions.lists.preview','tenant/admissions/lists','Admission lists','Preview and publish approved results.'],['admissions.acceptance.view','tenant/admissions/acceptance','Acceptance','Track responses and clearance handoff.'],['admissions.reports.view','tenant/admissions/reports','Reports','Use tenant-scoped operational reports.'],['admissions.audit.view','tenant/admissions/operations','Delivery operations','Inspect and retry failed notifications.']] as [$authority,$route,$label,$description]):?><?php if($can($authority)):?><a class="action-card" href="<?= site_url($route) ?>"><strong><?= esc($label) ?></strong><span class="muted"><?= esc($description) ?></span></a><?php endif?><?php endforeach?></section>
<div class="split-grid"><section class="panel"><h2>Active public cycle</h2><?php if($activeCycle===null):?><div class="empty">No active public admission cycle.</div><?php else:?><p><strong><?= esc($activeCycle['title']) ?></strong></p><?php endif?></section><section class="panel"><h2>Setup readiness</h2><?php if ($setupGaps === []): ?><p class="notice">Admission setup is ready for public discovery.</p><?php else: ?><ul><?php foreach ($setupGaps as $gap): ?><li><?= esc($gap) ?></li><?php endforeach ?></ul><?php endif ?></section></div>
<?= $this->endSection() ?>
